// <work-board> — a Kanban board. Composition-as-source: its slotted <work-task>
// children ARE the board; the board groups them into status columns by reading
// each task's `status` attribute (no JSON model — the elements are the truth).
//
// Each column is a named slot (slot="status-<key>"); on connect and on any child
// mutation the board assigns every <work-task> to the slot matching its status,
// so authors just drop tasks in any order and the board lays them out. A column
// header shows the status label + a live count.
//
// Attributes:
//   title    optional board heading
//   columns  comma-separated status keys to show (default: todo,doing,review,done,blocked)
import { WbElement, html, css, define } from "../../core/element.js";
import { STATUS, STATUS_ORDER, metaCss } from "./pm-shared.js";

export class WorkBoard extends WbElement {
  static props = ["title", "columns"];

  static styles = css`
    :host { display: block; font-family: var(--work-font); color: var(--work-fg); }
    .title { font-weight: 700; font-size: var(--work-text-lg); margin-bottom: var(--work-space-3); }
    .cols { display: grid; grid-auto-flow: column; grid-auto-columns: minmax(200px, 1fr); gap: var(--work-space-3); overflow-x: auto; align-items: start; }
    .col { display: flex; flex-direction: column; gap: var(--work-space-2);
      background: var(--work-surface-soft); border: 1px solid var(--work-border);
      border-radius: var(--work-radius-lg); padding: var(--work-space-3); min-height: 60px; }
    .chead { display: flex; align-items: center; gap: var(--work-space-2); }
    .clabel { font-weight: 600; font-size: var(--work-text-sm); }
    .count { margin-left: auto; font-family: var(--work-font-mono); font-size: var(--work-text-2xs);
      color: var(--work-fg-subtle); background: var(--work-surface); border: 1px solid var(--work-border);
      border-radius: var(--work-radius-pill); padding: 0 var(--work-space-2); }
    ::slotted(work-task) { margin-bottom: var(--work-space-2); }
    .dot { width: 8px; height: 8px; border-radius: var(--work-radius-pill); flex: none; background: var(--work-fg-subtle); }
    .dot[data-tone="brand"] { background: var(--work-brand); }
    .dot[data-tone="ok"] { background: var(--work-ok); }
    .dot[data-tone="warn"] { background: var(--work-warn); }
    .dot[data-tone="err"] { background: var(--work-err); }
    ${metaCss}
  `;

  static properties = { ...WbElement.properties, _counts: { state: true } };

  constructor() { super(); this._counts = {}; }

  connectedCallback() {
    super.connectedCallback();
    this._assign();
    this._mo = new MutationObserver(() => this._assign());
    this._mo.observe(this, { childList: true, subtree: false, attributes: true, attributeFilter: ["status"] });
  }
  disconnectedCallback() { super.disconnectedCallback(); this._mo?.disconnect(); }

  _columns() {
    const raw = this.attr("columns");
    return raw ? raw.split(",").map((c) => c.trim()).filter(Boolean) : STATUS_ORDER;
  }

  /** Route each <work-task> into the slot for its status; recompute counts. */
  _assign() {
    const cols = this._columns();
    const counts = Object.fromEntries(cols.map((c) => [c, 0]));
    for (const task of this.querySelectorAll(":scope > work-task")) {
      let status = task.getAttribute("status") || "todo";
      if (!cols.includes(status)) status = cols[0];
      task.setAttribute("slot", `status-${status}`);
      counts[status] = (counts[status] || 0) + 1;
    }
    this._counts = counts;
    this.requestUpdate();
  }

  render() {
    const title = this.attr("title");
    const cols = this._columns();
    return html`
      ${title ? html`<div class="title">${title}</div>` : ""}
      <div class="cols">
        ${cols.map((c) => {
          const s = STATUS[c] || { label: c, tone: "neutral" };
          return html`<div class="col">
            <div class="chead">
              <span class="dot" data-tone=${s.tone}></span>
              <span class="clabel">${s.label}</span>
              <span class="count">${this._counts[c] || 0}</span>
            </div>
            <slot name=${`status-${c}`}></slot>
          </div>`;
        })}
      </div>`;
  }
}

define("work-board", WorkBoard);

// WbElement — the base for every <wb-*> element, re-based onto Lit.
//
// Lit is the FLOOR's engine now (the approved adoption pass): surgical template
// updates instead of an innerHTML nuke, while every workponents convention is
// preserved so the rest of the library migrates mechanically. Lit is loaded as a
// bare specifier ("lit") — buildless via an import map in the demos, a peer dep
// for SDK consumers (see README / demo/lit-foundation.html). No bundler, no
// `bun install`.
//
// Conventions (unchanged — the whole library follows these):
//   • Shadow DOM (open) for style isolation; --work-* tokens inherit through it.
//   • `static styles` = the component CSS as a Lit `css``` CSSResult (was a
//     string). Use ONLY var(--work-*). Variants targeted via :host([name="value"]).
//   • `render()` returns a Lit `html``` TemplateResult (was a string) — surgical
//     updates, no innerHTML rewrite.
//   • `static props` = reflected attributes that re-render on change (variants,
//     state). They are mapped to Lit reactive properties automatically.
//   • `static variants` defaults are reflected on connect (before first paint) so
//     :host([name="value"]) selectors always match.
//   • Capability is reached through `this.host` (the Dock seam), never hardcoded.
//   • Register with `define()` (idempotent — safe to load twice).
//
// `attr()` / `boolAttr()` helpers are preserved for elements that read attributes
// directly in render(). Re-exports `html` + `css` so domain files import the whole
// authoring surface from one place:
//   import { WbElement, html, css, define } from "../core/element.js";

import { LitElement, html, css } from "lit";
import { getHost } from "./host.js";

export { html, css };

export class WbElement extends LitElement {
  /** @type {import("lit").CSSResult} component CSS — override with css``; use only var(--work-*) */
  static styles = css``;

  /** @type {string[]} reflected attributes that trigger a re-render */
  static props = [];

  // Register each subclass's `static props` as Lit reactive properties so an
  // attribute change fires attributeChangedCallback + re-renders (the old
  // observedAttributes contract). NOTE: a base-class `static get properties()` is
  // NOT honored — Lit's finalize() only reads each class's OWN `properties`. So we
  // hook finalize() and createProperty() per subclass instead. Reflect ONLY the
  // short variant enums (so el.variant = "soft" still matches :host([variant]));
  // never reflect data attributes like `rows`/`csv`/`query` (can be huge strings).
  static finalize() {
    super.finalize();
    const variants = this.variants || {};
    for (const name of this.props || []) {
      const key = this._propKey(name);
      // Skip names that already exist on the prototype as a method/getter (e.g. a
      // `variant(name)` helper, an `open()` method). Creating a reactive accessor
      // there THROWS in Lit dev mode ("declared as a reactive property but it's
      // actually declared as a value on the prototype"). The attribute is still
      // OBSERVED via observedAttributes below, so attribute changes still fire
      // attributeChangedCallback → the element's reload/requestUpdate runs.
      if (key in this.prototype) continue;
      this.createProperty(key, {
        type: String,
        attribute: name,
        reflect: Object.prototype.hasOwnProperty.call(variants, name),
      });
    }
  }

  // Guarantee every `static props` attribute is OBSERVED (the browser reads this
  // at customElements.define() time). This is the bulletproof half: even if Lit's
  // reactive-property finalize timing misses one, attribute changes still fire
  // attributeChangedCallback → the element's reload/requestUpdate handler runs.
  static get observedAttributes() {
    const base = super.observedAttributes || [];
    return Array.from(new Set([...base, ...(this.props || [])]));
  }

  // Attribute names may contain dashes; reactive-property keys must be identifiers.
  static _propKey(name) {
    return name.replace(/-([a-z])/g, (_, c) => c.toUpperCase());
  }

  /** The Dock/Host capability seam — local | runtime (RCP) | kernel. */
  get host() {
    return getHost();
  }

  /** Read an attribute with a default. */
  attr(name, fallback = null) {
    return this.hasAttribute(name) ? this.getAttribute(name) : fallback;
  }

  /** Read a boolean attribute (present = true). */
  boolAttr(name) {
    return this.hasAttribute(name);
  }

  /** Override: return the template (Lit `html```). */
  render() {
    return html`<slot></slot>`;
  }

  connectedCallback() {
    // Reflect default variants BEFORE Lit's first render so :host([name="value"])
    // selectors match the very first paint, even when the author sets only some
    // (e.g. tone without variant).
    const v = this.constructor.variants;
    if (v) {
      for (const [name, def] of Object.entries(v)) {
        if (!this.hasAttribute(name)) this.setAttribute(name, def.default);
      }
    }
    super.connectedCallback();
  }
}

/** Idempotent custom-element registration (safe across double-loads). */
export function define(name, ctor) {
  if (!customElements.get(name)) customElements.define(name, ctor);
  return ctor;
}

// The Host/Dock seam — one capability surface for every element.
//
// A workponent never hardcodes where a capability runs. It asks the Host, which
// resolves `local` (in-WASM / browser-native), `runtime` (a Workbooks runtime
// over RCP), or `kernel` (oql.wasm) per the platform-model — so the SAME element
// (e.g. <wb-table>) runs in-WASM locally or on the runtime tier for huge data,
// no code fork. Capability elements declare what they need; the Host provisions
// it (the same grant model toolkits use) and reports availability so the element
// degrades cleanly when a capability is absent (e.g. voice without a key).
//
// Phase 0: a minimal, portable seam (no Tauri/Svelte). When a runtime URL is
// configured it routes over fetch/WebSocket (mirroring desktop/src/lib/rcp);
// otherwise it serves local capabilities and reports the rest unavailable.

let _host = null;

export class WbHost {
  /** @param {{ runtimeUrl?: string|null, tenant?: string }} [opts] */
  constructor(opts = {}) {
    this.runtimeUrl = opts.runtimeUrl || null;
    this.tenant = opts.tenant || "local";
    this._caps = new Set(["local"]); // in-WASM/browser caps are always present
  }

  /** Is a capability reachable here? (elements gate UI on this) */
  available(cap) {
    return this._caps.has(cap) || (this.runtimeUrl != null && cap !== "voice");
  }

  /** Unary capability call — routed to the runtime when present. */
  async request(path, { method = "POST", body } = {}) {
    if (!this.runtimeUrl) throw new Error(`wb-host: no runtime for ${path}`);
    const res = await fetch(this.runtimeUrl.replace(/\/$/, "") + path, {
      method,
      headers: { "content-type": "application/json", "x-tenant": this.tenant },
      body: body != null ? JSON.stringify(body) : undefined,
    });
    if (!res.ok) throw new Error(`wb-host ${res.status} ${path}`);
    return res.json();
  }

  /** Streaming capability — a WebSocket to the runtime. */
  socket(path, { onMessage } = {}) {
    if (!this.runtimeUrl) throw new Error(`wb-host: no runtime for ${path}`);
    const url = this.runtimeUrl.replace(/^http/, "ws").replace(/\/$/, "") + path;
    const ws = new WebSocket(url);
    if (onMessage) ws.addEventListener("message", (e) => onMessage(e.data));
    return ws;
  }
}

/** Configure the shared Host (call once at app/workbook boot). */
export function configureHost(opts) {
  _host = new WbHost(opts);
  return _host;
}

/** The shared Host singleton (a local-only Host by default). */
export function getHost() {
  if (!_host) {
    // Honor a global hint (a workbook/desktop can set window.__WB_RUNTIME_URL__).
    const url = typeof window !== "undefined" ? window.__WB_RUNTIME_URL__ : null;
    _host = new WbHost({ runtimeUrl: url || null });
  }
  return _host;
}

// pm-shared — the small DRY layer for the PM + flow structural elements.
// Status tones, priority enum, the meta-row CSS, and the field/initials helpers
// are authored ONCE here and reused by work-task / work-board / work-sprint /
// work-milestone / work-flow / work-loop. Every component renders its own
// attributes (no post-hoc regex chrome); these just keep that rendering uniform
// and token-only (var(--work-*) exclusively).
import { html, css } from "../../core/element.js";

// status → { label, tone } where tone selects the pill color via [data-tone].
// One canonical status vocabulary across PM + flow (the org TODO/DONE state,
// re-expressed as a plain attribute; see docs/WORK-FORMAT.md).
export const STATUS = {
  todo:    { label: "To do",   tone: "neutral" },
  doing:   { label: "Doing",   tone: "brand" },
  review:  { label: "Review",  tone: "warn" },
  done:    { label: "Done",    tone: "ok" },
  blocked: { label: "Blocked", tone: "err" },
  // flow/loop runtime states share the same pill machinery
  idle:    { label: "Idle",    tone: "neutral" },
  running: { label: "Running", tone: "brand" },
  paused:  { label: "Paused",  tone: "warn" },
  failed:  { label: "Failed",  tone: "err" },
  ok:      { label: "OK",      tone: "ok" },
};

export const STATUS_ORDER = ["todo", "doing", "review", "done", "blocked"];
export const PRIORITY = ["low", "med", "high", "urgent"];

/** Two-letter initials for an avatar chip from an assignee/owner string. */
export function initials(name) {
  return String(name || "")
    .replace(/^@/, "")
    .split(/[\s._-]+/)
    .filter(Boolean)
    .map((w) => w[0])
    .join("")
    .slice(0, 2)
    .toUpperCase() || "?";
}

/** A labeled inline meta field; renders nothing when the value is empty. */
export function fieldRow(label, value) {
  return value ? html`<span class="field"><span class="flabel">${label}</span>${value}</span>` : "";
}

/** The status pill markup, given a status key (falls back to neutral/unknown). */
export function pill(status) {
  const s = STATUS[status] || { label: status || "—", tone: "neutral" };
  return html`<span class="pill" data-tone=${s.tone}>${s.label}</span>`;
}

// Shared meta-row + pill CSS — spliced into each element's `static styles` so the
// status pills, avatars and field chips look identical everywhere. Token-only.
export const metaCss = css`
  .meta { display: flex; flex-wrap: wrap; align-items: center; gap: var(--work-space-2) var(--work-space-3); font-size: var(--work-text-sm); color: var(--work-fg-muted); }
  .field { display: inline-flex; align-items: center; gap: var(--work-space-1); }
  .flabel { font-family: var(--work-font-mono); font-size: var(--work-text-2xs); text-transform: uppercase; letter-spacing: .05em; color: var(--work-fg-subtle); }
  .who { display: inline-flex; align-items: center; gap: var(--work-space-1); }
  .avatar { display: inline-grid; place-items: center; width: 20px; height: 20px; border-radius: var(--work-radius-pill);
    background: var(--work-brand-soft); color: var(--work-fg); font-size: var(--work-text-2xs); font-weight: 700; border: 1px solid var(--work-border); }

  .pill { display: inline-flex; align-items: center; padding: 1px var(--work-space-2); border-radius: var(--work-radius-pill);
    font-size: var(--work-text-2xs); font-weight: 600; line-height: 1.5; white-space: nowrap;
    border: 1px solid var(--work-border); background: var(--work-surface-soft); color: var(--work-fg-muted); }
  .pill[data-tone="brand"] { border-color: color-mix(in srgb, var(--work-brand) 45%, transparent); background: var(--work-brand-soft); color: var(--work-brand-ink); }
  .pill[data-tone="ok"]    { border-color: color-mix(in srgb, var(--work-ok) 45%, transparent);   background: var(--work-ok-soft);   color: var(--work-ok); }
  .pill[data-tone="warn"]  { border-color: color-mix(in srgb, var(--work-warn) 45%, transparent); background: var(--work-warn-soft); color: var(--work-warn); }
  .pill[data-tone="err"]   { border-color: color-mix(in srgb, var(--work-err) 45%, transparent);  background: var(--work-err-soft);  color: var(--work-err); }
`;
